import{a as e,c as t,i as n}from"./app-DWPqdE41.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";var i=JSON.parse(`{"path":"/Linux/loadbalancing/loadbalancing-01-keepalived-vip-lvs.html","title":"网关高可用从 0 到大厂形态——keepalived、VIP 漂移与 LVS 接入层","lang":"zh-CN","frontmatter":{"title":"网关高可用从 0 到大厂形态——keepalived、VIP 漂移与 LVS 接入层","sidebarGroup":"负载均衡与高可用","shortTitle":"01 keepalived+VIP 漂移与 LVS","order":1,"date":"2026-09-16T00:00:00.000Z","category":"Linux","tag":["Linux","keepalived","LVS","VIP","高可用","APISIX"],"description":"从\\"网关挂了全公司断网\\"这个单点问题出发，在两台容器上从 0 部署 keepalived + VIP 漂移，实测三幕故障演练；拆开四层与七层的区别，用内核 IPVS 实测 LVS 轮询分流、后端宕机翻车与扩容；最后对比公司两台同机形态与大厂 LVS 接入层分层形态，附完整配置模板与生产检查表。","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"网关高可用从 0 到大厂形态——keepalived、VIP 漂移与 LVS 接入层\\",\\"image\\":[\\"https://www.code-corey.com/Linux/loadbalancing/img-003.png\\",\\"https://www.code-corey.com/Linux/loadbalancing/img-001.png\\",\\"https://www.code-corey.com/Linux/loadbalancing/img-002.png\\"],\\"datePublished\\":\\"2026-09-16T00:00:00.000Z\\",\\"dateModified\\":\\"2026-09-17T05:30:38.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"Corey\\",\\"url\\":\\"https://www.code-corey.com\\"}]}"],["meta",{"property":"og:url","content":"https://www.code-corey.com/Linux/loadbalancing/loadbalancing-01-keepalived-vip-lvs.html"}],["meta",{"property":"og:site_name","content":"Corey 知识库"}],["meta",{"property":"og:title","content":"网关高可用从 0 到大厂形态——keepalived、VIP 漂移与 LVS 接入层"}],["meta",{"property":"og:description","content":"从\\"网关挂了全公司断网\\"这个单点问题出发，在两台容器上从 0 部署 keepalived + VIP 漂移，实测三幕故障演练；拆开四层与七层的区别，用内核 IPVS 实测 LVS 轮询分流、后端宕机翻车与扩容；最后对比公司两台同机形态与大厂 LVS 接入层分层形态，附完整配置模板与生产检查表。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://www.code-corey.com/Linux/loadbalancing/img-003.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-09-17T05:30:38.000Z"}],["meta",{"property":"article:tag","content":"APISIX"}],["meta",{"property":"article:tag","content":"高可用"}],["meta",{"property":"article:tag","content":"VIP"}],["meta",{"property":"article:tag","content":"LVS"}],["meta",{"property":"article:tag","content":"keepalived"}],["meta",{"property":"article:tag","content":"Linux"}],["meta",{"property":"article:published_time","content":"2026-09-16T00:00:00.000Z"}],["meta",{"property":"article:modified_time","content":"2026-09-17T05:30:38.000Z"}]]},"git":{"createdTime":1789610877000,"updatedTime":1789623038000,"contributors":[{"name":"chengongyi","username":"chengongyi","email":"2363613998@qq.com","commits":3,"url":"https://github.com/chengongyi"}]},"readingTime":{"minutes":26.98,"words":8095},"filePathRelative":"Linux/loadbalancing/loadbalancing-01-keepalived-vip-lvs.md","excerpt":"<blockquote>\\n<p><strong>负载均衡与高可用 · 第 1 篇</strong>（开篇）<br>\\n下一篇：系列完结（规划中：《keepalived 脑裂与仲裁》《LVS DR 模式与公网接入》）</p>\\n</blockquote>\\n<hr>\\n<h2>〇、先说人话：全文就四句话</h2>\\n<p>费曼技巧第一步：假装把这篇文章讲给一个完全没碰过运维的朋友听。全部内容，其实就四句话：</p>\\n<ol>\\n<li>网关是全公司流量的大门。只装一扇门，门塌了全公司断网——所以装两扇一模一样的。</li>\\n<li>可客户端只认一个地址，怎么办？给两扇门挂同一块门牌（VIP）：同一时刻门牌只钉在一扇门上，塌了自动搬到另一扇。负责搬门牌的软件，叫 keepalived。</li>\\n<li>以后门多到三扇以上、流量扛不住了，就在所有门前再盖一间传达室（LVS）：它不拆包裹、只看信封，照一张名单把包裹轮流分下去——又快又便宜。</li>\\n<li>但传达室不是标配：网关不超过 3 台，每台自带一块 keepalived 门牌（&quot;同机形态&quot;）就是最优解，绝大多数公司到这一步就够了。</li>\\n</ol>"}`),a={name:`loadbalancing-01-keepalived-vip-lvs.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<blockquote><p><strong>负载均衡与高可用 · 第 1 篇</strong>（开篇）<br> 下一篇：系列完结（规划中：《keepalived 脑裂与仲裁》《LVS DR 模式与公网接入》）</p></blockquote><hr><h2 id="〇、先说人话-全文就四句话" tabindex="-1"><a class="header-anchor" href="#〇、先说人话-全文就四句话"><span>〇、先说人话：全文就四句话</span></a></h2><p>费曼技巧第一步：假装把这篇文章讲给一个完全没碰过运维的朋友听。全部内容，其实就四句话：</p><ol><li>网关是全公司流量的大门。只装一扇门，门塌了全公司断网——所以装两扇一模一样的。</li><li>可客户端只认一个地址，怎么办？给两扇门挂同一块门牌（VIP）：同一时刻门牌只钉在一扇门上，塌了自动搬到另一扇。负责搬门牌的软件，叫 keepalived。</li><li>以后门多到三扇以上、流量扛不住了，就在所有门前再盖一间传达室（LVS）：它不拆包裹、只看信封，照一张名单把包裹轮流分下去——又快又便宜。</li><li>但传达室不是标配：网关不超过 3 台，每台自带一块 keepalived 门牌（&quot;同机形态&quot;）就是最优解，绝大多数公司到这一步就够了。</li></ol><p>后面十节，只是把这四句话一句句展开成能上线的配置。哪天你能不看文章把这四句讲顺，这篇就算学会了。</p><hr><h2 id="一、问题-全公司只有一扇门" tabindex="-1"><a class="header-anchor" href="#一、问题-全公司只有一扇门"><span>一、问题：全公司只有一扇门</span></a></h2><p>一句话本质：一台网关就是全公司的单点。单点的意思是——它一个人挂，所有人陪葬。</p><p>想象你给公司上了 API 网关，所有前端的 baseURL 都指向它。某天这台机器的内存条坏了：重启、换件、恢复路由，运气不好要折腾一下午。这一下午里挂掉的不是某一个系统，是所有系统。</p><p>解法听起来朴素：再买一台，两台干一样的活。但新问题立刻冒出来——</p><blockquote><p>前端到底连哪台的 IP？</p></blockquote><p>连 A，A 挂了照样断；连 B 同理。让前端记两个 IP 自己切换？每个前端都得改代码、每个用户都得刷新页面。工程上对这个问题有统一答案，就是本文第一个主角：VIP（Virtual IP，虚拟 IP）。</p><hr><h2 id="二、vip-一块会搬家的大门牌" tabindex="-1"><a class="header-anchor" href="#二、vip-一块会搬家的大门牌"><span>二、VIP：一块会搬家的大门牌</span></a></h2><p>先纠正最容易想歪的地方：VIP 一点都不&quot;虚拟&quot;，它就是一个普普通通的 IP 地址。它的特殊之处只有一条规矩——同一时刻，全网络只许一台机器的网卡上挂着它。挂在谁家，流量就进谁家。</p><p>（网卡：机器上插网线的那块硬件。IP 地址本来就可以理解成钉在网卡上的门牌号，而 VIP 是一块公共的、会搬家的门牌。）</p><p>我在实验室起了两台容器当真机：KA1（172.67.0.21）和 KA2（172.67.0.22）。给 KA1 跑上 keepalived 后，看它的网卡：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ip -4 addr show eth0</span></span>
<span class="line"><span>    inet 172.67.0.21/24 brd 172.67.0.255 scope global eth0</span></span>
<span class="line"><span>    inet 172.67.0.20/24 scope global secondary eth0    ← VIP 钉在这里</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>同一时刻，KA2 的网卡上没有这个地址：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ip -4 addr show eth0        # 在 KA2 上执行</span></span>
<span class="line"><span>    inet 172.67.0.22/24 brd 172.67.0.255 scope global eth0</span></span>
<span class="line"><span>    （没有 172.67.0.20 —— 门牌不在它家）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>于是两种 IP 的分工清楚了：</p><table><thead><tr><th>角色</th><th>是什么</th><th>干的活</th></tr></thead><tbody><tr><td>KA1 / KA2 各自的 IP</td><td>工位号</td><td>管理员 ssh 上去维护用，用户不认识它</td></tr><tr><td>VIP（172.67.0.20）</td><td>公共门牌</td><td>用户和 DNS 只认它；钉在谁家，流量进谁家</td></tr></tbody></table><p>keepalived 的全部工作，就是决定这块门牌此刻钉在谁家：机器挂了，它把门牌搬到备胎家；修好了，再搬回来。注意它自始至终不碰业务流量，一个字节都不碰——证据放在第四节，先卖个关子。</p><h3 id="_2-1-下钻一层-linux-内核里根本没有-虚拟-ip" tabindex="-1"><a class="header-anchor" href="#_2-1-下钻一层-linux-内核里根本没有-虚拟-ip"><span>2.1 下钻一层：Linux 内核里根本没有&quot;虚拟 IP&quot;</span></a></h3><p>把窗户纸捅破：Linux 内核里没有&quot;虚拟 IP&quot;这个概念，也没有任何&quot;VIP 开关&quot;。VIP 能存在，靠的是内核一个最普通的能力——一块网卡可以挂多个 IP 地址。</p><p>机制就两层：</p><ol><li>每块网卡在内核里就是一张地址清单。包到达时内核查清单：目的地址在清单里 → &quot;这封信是寄给我的&quot;，收下交给上层；不在 → 该转发的转发，该丢的丢。所谓&quot;VIP 钉在谁家&quot;，翻译成内核语言就是&quot;谁的清单里有这条记录&quot;。</li><li>地址挂上去的同时，内核自动把它登记进一张叫 local 的路由表——本机收件名单。在名单里的地址，内核才认作&quot;我的&quot;。</li></ol><p>不装任何软件，root 手工就能当一次 keepalived（以下在 WSL2 Ubuntu 里实测）：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ip addr add 172.67.0.20/24 dev eth0     # 给网卡挂上本文同款 VIP</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ip -4 addr show eth0</span></span>
<span class="line"><span>2: eth0: &lt;BROADCAST,MULTICAST,UP,LOWER_UP&gt; mtu 1500 qdisc mq state UP group default qlen 1000</span></span>
<span class="line"><span>    inet 172.22.212.111/20 brd 172.22.223.255 scope global eth0</span></span>
<span class="line"><span>    inet 172.67.0.20/24 scope global eth0   ← 多出一行，没有任何&quot;虚拟&quot;标记</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>细心的读者会发现：这里没有 KA1 输出里的 secondary 标记。secondary 的含义很朴素——只有和已有主地址同子网的第二个地址才标 secondary（KA1 的 VIP 172.67.0.20/24 与本机 IP 172.67.0.21/24 同网段，所以标了）；这台 WSL 的网卡原本在 172.22.x 段，172.67.0.20 对它是另一个子网，于是各自都是主地址。标记而已，待遇一模一样。</p><p>再看内核自动登记的收件名单：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ip route show table local | grep 172.67.0.20</span></span>
<span class="line"><span>local 172.67.0.20 dev eth0 proto kernel scope host src 172.67.0.20</span></span>
<span class="line"><span>broadcast 172.67.0.255 dev eth0 proto kernel scope link src 172.67.0.20</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>local ... scope host</code> 这行就是&quot;172.67.0.20 是本机地址&quot;的正式登记，<code>ip addr add</code> 自动送的，不用手工登记。验证名单生效：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ping -c 2 172.67.0.20</span></span>
<span class="line"><span>PING 172.67.0.20 (172.67.0.20) 56(84) bytes of data.</span></span>
<span class="line"><span>64 bytes from 172.67.0.20: icmp_seq=1 ttl=64 time=0.037 ms</span></span>
<span class="line"><span>64 bytes from 172.67.0.20: icmp_seq=2 ttl=64 time=0.044 ms</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>0.037 毫秒——包根本没出这台机器：内核在收件名单里查到&quot;这是我的地址&quot;，直接在内存里转了一圈还回来。最后摘掉门牌：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ip addr del 172.67.0.20/24 dev eth0</span></span>
<span class="line"><span>$ ip -4 addr show eth0 | grep -c 172.67.0.20</span></span>
<span class="line"><span>0</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>结论：VIP 的&quot;挂上/摘下&quot;，在内核层面就是 <code>ip addr add</code> / <code>ip addr del</code> 一行命令的事。</p><h3 id="_2-2-那-keepalived-到底自动化了什么" tabindex="-1"><a class="header-anchor" href="#_2-2-那-keepalived-到底自动化了什么"><span>2.2 那 keepalived 到底自动化了什么</span></a></h3><p>把手工流程和 keepalived 对齐：</p><table><thead><tr><th>手工</th><th>keepalived</th><th>说明</th></tr></thead><tbody><tr><td>你盯着两台机器，谁挂了手动敲命令</td><td>VRRP 心跳（IP 协议号 112）自动选主</td><td>&quot;谁挂了&quot;不用人盯</td></tr><tr><td><code>ip addr add</code> / <code>ip addr del</code></td><td>内部走 netlink 接口，效果与命令等价</td><td>netlink = 内核提供给程序的&quot;命令行&quot;</td></tr><tr><td>手工做不了：挨家挨户通知邻居</td><td>广播免费 ARP（GARP）：&quot;172.67.0.20 的 MAC 是我&quot;</td><td>刷新全网交换机与邻居的 ARP 缓存</td></tr></tbody></table><p>3.6 节实测的&quot;约 6 秒接管&quot;，拆开正是：约 3 秒心跳判死（3 × advert_int）+ 免费 ARP 全网刷新交换机表项的零点几到几秒。keepalived 没有魔法——它是&quot;选主 + 改地址清单 + 喊一嗓子&quot;三件事的自动化套装。</p><p>（再往下一层还有戏：LVS 的 DR 模式会把 VIP 挂到 lo 回环设备上并做 ARP 抑制，那是下一篇的主角，按下不表。）</p><p>把这两小节拼成一张图：左侧是数据面（流量照着 ARP 缓存找到持牌的 KA1，进 eth0 清单、查 local 名单、交给应用），右侧是待命的 KA2；keepalived 只在控制面干活——底部实线是每秒心跳，顶部虚线是免费 ARP 广播，netlink 是它改写地址清单的那支笔。</p><p><img src="/assets/img-003-KGt8ap9f.png" alt="VIP 的 Linux 实现：内核地址清单 + keepalived 三板斧" loading="lazy"></p><p>这节收束成一句：VIP 负责&quot;地址不变&quot;，keepalived 负责&quot;地址搬家&quot;，业务自己负责&quot;接电话&quot;。</p><hr><h2 id="三、keepalived-从-0-到上岗-七步实测" tabindex="-1"><a class="header-anchor" href="#三、keepalived-从-0-到上岗-七步实测"><span>三、keepalived 从 0 到上岗：七步实测</span></a></h2><p>以下每条命令都在两台 Ubuntu 22.04 容器上真实跑过，可以照抄复现。</p><h3 id="_3-1-第-0-步-规划——先填表再动手" tabindex="-1"><a class="header-anchor" href="#_3-1-第-0-步-规划——先填表再动手"><span>3.1 第 0 步：规划——先填表再动手</span></a></h3><table><thead><tr><th>角色</th><th>机器</th><th>机上跑的业务</th><th>priority</th></tr></thead><tbody><tr><td>KA1</td><td>172.67.0.21</td><td>nginx（或 APISIX）</td><td>100（大哥）</td></tr><tr><td>KA2</td><td>172.67.0.22</td><td>同样的业务</td><td>90（备胎）</td></tr><tr><td>VIP</td><td>172.67.0.20</td><td>—— 用户只连这个</td><td>——</td></tr></tbody></table><p>三条铁律：两台必须同一网段（心跳靠二层广播，可以理解成两台机器得在同一个村子里互相喊得应）；<code>virtual_router_id</code> 两台必须一致（小队编号）；priority 谁大谁持有 VIP。</p><h3 id="_3-2-第-1-步-装软件-两台都执行" tabindex="-1"><a class="header-anchor" href="#_3-2-第-1-步-装软件-两台都执行"><span>3.2 第 1 步：装软件（两台都执行）</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">apt-get</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> update</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> &amp;&amp; </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">apt-get</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> install</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -y</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> keepalived</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> nginx</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>装完会自建空的 <code>/etc/keepalived/</code> 目录，服务起不来属正常——配置还没写。</p><h3 id="_3-3-第-2-步-写配置-两台只差两行" tabindex="-1"><a class="header-anchor" href="#_3-3-第-2-步-写配置-两台只差两行"><span>3.3 第 2 步：写配置（两台只差两行）</span></a></h3><p>KA1 的 <code>/etc/keepalived/keepalived.conf</code>，逐行翻译成人话：</p><div class="language-conf line-numbers-mode" data-highlighter="shiki" data-ext="conf" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-conf"><span class="line"><span>vrrp_instance VI_1 {              # 一组&quot;抢IP小队&quot;，名字随便取</span></span>
<span class="line"><span>    state MASTER                  # 初始角色（KA2 上写 BACKUP）     ← 差异①</span></span>
<span class="line"><span>    interface eth0                # 心跳和VIP绑在哪块网卡</span></span>
<span class="line"><span>    virtual_router_id 61          # 小队编号 0~255，两台必须相同</span></span>
<span class="line"><span>    priority 100                  # 权位，谁大谁持有VIP（KA2 写 90） ← 差异②</span></span>
<span class="line"><span>    advert_int 1                  # 心跳间隔1秒</span></span>
<span class="line"><span>    virtual_ipaddress {</span></span>
<span class="line"><span>        172.67.0.20/24            # 大家争夺的VIP</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>名词随手解释：VRRP（虚拟路由冗余协议）一句话版本——几台机器定期互相喊&quot;我还在&quot;（喊话就是心跳），谁权位高谁持有公共 IP；<code>vrrp_instance</code> 就是一支这样的小队，<code>advert_int</code> 是喊话间隔。</p><p>网卡名别猜，用 <code>ip route | awk &#39;/default/ {print $5}&#39;</code> 查真实名字（可能是 <code>ens192</code>、<code>enp0s3</code>）。KA2 的配置就是把 <code>MASTER</code> 改 <code>BACKUP</code>、<code>100</code> 改 <code>90</code>，其余逐字节一致。</p><p>三个容易想歪的点（想歪了就不算学会）：</p><ol><li><code>state</code> 只是开机初始站位，真正说了算的是 <code>priority</code>——就算 KA1 写着 <code>state MASTER</code> 但 priority 只有 50，KA2（BACKUP/90）照样把它摁下去</li><li><code>virtual_router_id</code> 和 VIP 两台必须一致，差一个字符就是两支互不认账的小队，各抢各的</li><li>以后任何改动（心跳间隔、换 VIP）都要两台同步改，只许 state/priority 各自维护</li></ol><h3 id="_3-4-第-3-步-启动-两台" tabindex="-1"><a class="header-anchor" href="#_3-4-第-3-步-启动-两台"><span>3.4 第 3 步：启动（两台）</span></a></h3><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">systemctl</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> enable</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --now</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> keepalived</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">systemctl</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> status</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> keepalived</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">       # active (running)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-5-第-4-步-验收" tabindex="-1"><a class="header-anchor" href="#_3-5-第-4-步-验收"><span>3.5 第 4 步：验收</span></a></h3><p>验收就两条：门牌在 KA1 家、curl VIP 是 KA1 应答。</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ip</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> addr</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> show</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> eth0</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> | </span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">grep</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 172.67.0.20</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # KA1 上能看到 = 对；KA2 上没有 = 对</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">curl</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http://172.67.0.20/</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">                # 应答内容 = KA1 的页面</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>我给两台各放了一个自我介绍页面，此刻访问 VIP：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ curl http://172.67.0.20/</span></span>
<span class="line"><span>我是 KA1 (MASTER 172.67.0.21)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-6-第-5-步-故障演练——上岗前必做" tabindex="-1"><a class="header-anchor" href="#_3-6-第-5-步-故障演练——上岗前必做"><span>3.6 第 5 步：故障演练——上岗前必做</span></a></h3><p>三幕剧，输出全部真实。</p><p>第一幕，正常状态：VIP 在 KA1 网卡上，curl VIP 是 KA1 应答（见上文）。</p><p>第二幕，KA1 猝死——kill 掉它的 keepalived：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ docker exec ka1 pkill keepalived</span></span>
<span class="line"><span>  第1秒: KA2 网卡上 VIP 已出现 ✓</span></span>
<span class="line"><span>$ curl http://172.67.0.20/</span></span>
<span class="line"><span>我是 KA2 (BACKUP 172.67.0.22)</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意一个细节：KA1 上的 nginx 还活着，但门牌已经不在它家——没有流量再找它了。&quot;机器活着但没生意&quot;，正是 VIP 机制和&quot;重启机器&quot;的本质区别。</p><p>第三幕，KA1 修好复活：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ systemctl start keepalived        # KA1 上执行</span></span>
<span class="line"><span>$ ip addr show eth0 | grep 172.67.0.20</span></span>
<span class="line"><span>    inet 172.67.0.20/24 scope global secondary eth0</span></span>
<span class="line"><span>$ curl http://172.67.0.20/</span></span>
<span class="line"><span>我是 KA1 (MASTER 172.67.0.21)       ← priority 100 &gt; 90，大哥回归抢回门牌</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>看全程内幕的最佳位置是 <code>journalctl -u keepalived -f</code>，两台都开着，能实时看到&quot;心跳丢失 → 接管&quot;和&quot;大哥回归 → 让位&quot;的日志对白。</p><p>&quot;几秒接管&quot;这笔账要算得清：BACKUP 连续 3 个心跳没收到才判定对方死亡（<code>3 × advert_int</code> ≈ 3 秒），加上免费 ARP 广播刷新全网交换机的地址表（ARP：地址解析协议，全网共用的&quot;IP 对应哪块网卡&quot;登记表，门牌搬了家要全网重新登记），整容器拔网线实测约 6 秒，真机断电场景按 3~4 秒预期——用户浏览器会自动重试，基本无感。</p><h3 id="_3-7-第-6-步-聪明让位-track-script-强烈建议加" tabindex="-1"><a class="header-anchor" href="#_3-7-第-6-步-聪明让位-track-script-强烈建议加"><span>3.7 第 6 步：聪明让位（track_script，强烈建议加）</span></a></h3><p>上面的配置只防&quot;机器死了&quot;。还有一种更阴险的情况：机器活得好好的，但网关进程死了——门牌不会动，流量继续打进一台&quot;活着的死机器&quot;。加一段体检解决：</p><div class="language-conf line-numbers-mode" data-highlighter="shiki" data-ext="conf" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-conf"><span class="line"><span>global_defs {</span></span>
<span class="line"><span>    enable_script_security        # 配了体检脚本就必须开这两行, 否则 keepalived 拒绝启动</span></span>
<span class="line"><span>    script_user root</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vrrp_script chk_nginx {</span></span>
<span class="line"><span>    script &quot;/usr/bin/curl -s -o /dev/null http://127.0.0.1/&quot;   # 探活本机业务</span></span>
<span class="line"><span>    interval 3       # 每3秒查一次</span></span>
<span class="line"><span>    weight -30       # 查不通→priority减30（100变70，低于90，自动让位）</span></span>
<span class="line"><span>    fall 2           # 连续失败2次才算真死（防网络抖动误杀）</span></span>
<span class="line"><span>    rise 2           # 连续成功2次才算复活（防反复横跳）</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>vrrp_instance VI_1 {</span></span>
<span class="line"><span>    state MASTER                   # KA2: BACKUP</span></span>
<span class="line"><span>    interface eth0</span></span>
<span class="line"><span>    virtual_router_id 61</span></span>
<span class="line"><span>    priority 100                   # KA2: 90</span></span>
<span class="line"><span>    advert_int 1</span></span>
<span class="line"><span>    virtual_ipaddress {</span></span>
<span class="line"><span>        172.67.0.20/24</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    track_script { chk_nginx }     # 相对 3.3 的配置, 真正新增的就这一行</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>翻译：给小队加一条家规——本人重病（业务端口探不通），就算机器还活着也得让出门牌。</p><h3 id="_3-8-第-7-步-上岗" tabindex="-1"><a class="header-anchor" href="#_3-8-第-7-步-上岗"><span>3.8 第 7 步：上岗</span></a></h3><p>keepalived 只管门牌不碰业务。把业务（nginx / APISIX / 别的什么）在两台都跑起来，前端和 DNS 全部指向 VIP，完事。</p><hr><h2 id="四、keepalived-和-apisix-是怎么配合的" tabindex="-1"><a class="header-anchor" href="#四、keepalived-和-apisix-是怎么配合的"><span>四、keepalived 和 APISIX 是怎么配合的</span></a></h2><p>最多人想岔的一步：&quot;keepalived 怎么把数据转给 APISIX？&quot;——它不转，一个字节都不转。它俩之间没有 API、没有调用、没有对话。两个证据。</p><p>证据一，看谁在监听端口。在网关机上：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ss -tlnp | grep 9080</span></span>
<span class="line"><span>LISTEN 0 511 0.0.0.0:9080 0.0.0.0:*  users:((&quot;openresty&quot;,pid=1,fd=20))  ← APISIX 的内核</span></span>
<span class="line"><span>（keepalived 不在任何 TCP 端口上——它的心跳是 IP 协议号 112，根本不走 TCP/UDP 端口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ ps aux | grep keepalived</span></span>
<span class="line"><span>root  3853  0.0  0.0  27832  2544 ?  Ss  Sep16  0:00 keepalived -D -f /etc/keepalived/keepalived.conf   ← 活着，但不接客</span></span>
<span class="line"><span>root  3854  0.0  0.0  27832  3184 ?  S   Sep16  0:16 keepalived -D -f /etc/keepalived/keepalived.conf      （父子两个进程: 主进程管心跳, 子进程管体检）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>证据二，让两台网关的流水账（access log）说话。网关集群正常时打一发请求，账记在持 VIP 的 M1 头上：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>172.66.0.1 - - [16/Sep/2026:12:43:46 +0000] 172.66.0.100:9080 &quot;GET /hello HTTP/1.1&quot; 200 30 0.001 &quot;-&quot; &quot;curl/7.81.0&quot; 172.66.0.51:80 200 0.001 &quot;http://172.66.0.100:9080&quot; &quot;bfab6dec94b658bacede7f37c8aad5ba&quot;</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>停掉 M1 的 keepalived、等 VIP 漂到 M2，再打一发：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>172.66.0.1 - - [16/Sep/2026:12:43:52 +0000] 172.66.0.100:9080 &quot;GET /hello HTTP/1.1&quot; 200 30 0.001 &quot;-&quot; &quot;curl/7.81.0&quot; 172.66.0.51:80 200 0.001 &quot;http://172.66.0.100:9080&quot; &quot;75b5e812ef179f96c869913f6c74f7a8&quot;</span></span>
<span class="line"><span>（这条出现在 M2 的日志里——同一时刻 M1 的日志没有新增）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>复活 M1，等门牌搬回来再打：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>172.66.0.1 - - [16/Sep/2026:12:45:34 +0000] 172.66.0.100:9080 &quot;GET /hello HTTP/1.1&quot; 200 30 0.001 &quot;-&quot; &quot;curl/7.81.0&quot; 172.66.0.51:80 200 0.001 &quot;http://172.66.0.100:9080&quot; &quot;0ac140cfa78e437cae56dce7ab201df3&quot;</span></span>
<span class="line"><span>（这条回到 M1 的日志里）</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>结论一句话：请求打到 VIP，永远是&quot;此刻网卡上挂着 VIP 的那台机器&quot;里的网关接单记账。数据是照着门牌自己找上门的，不是谁转交给 APISIX 的。</p><p>那&quot;配合&quot;靠什么？靠一份三方契约，三方互相不说话：</p><table><thead><tr><th>契约条款</th><th>谁负责</th><th>违约后果</th></tr></thead><tbody><tr><td>① 网关必须监听 <code>0.0.0.0</code>，不能写死自己 IP</td><td>网关的配置文件</td><td>写死 <code>192.168.1.31</code> → VIP 漂过来也没人接电话，经典翻车点</td></tr><tr><td>② 两台网关认识完全相同的路由</td><td>etcd 同步</td><td>路由不一致 → 漂移瞬间&quot;换了一家公司&quot;，部分接口 404</td></tr><tr><td>③ 机器活着但网关死了也要让位</td><td>keepalived 的 track_script</td><td>不配 → 半死机状态，VIP 不漂，流量黑洞</td></tr></tbody></table><p><img src="/assets/img-001-4qxfHGhu.png" alt="公司网关两台同机形态" loading="lazy"></p><p>看图注意一件事：keepalived 和 APISIX 两个进程之间没有任何通信。这正是这个架构简洁的地方——把 APISIX 换成 nginx 或任何别的网关，keepalived 的配置一个字都不用改。</p><hr><h2 id="五、四层与七层-看信封-vs-拆信读信" tabindex="-1"><a class="header-anchor" href="#五、四层与七层-看信封-vs-拆信读信"><span>五、四层与七层：看信封 vs 拆信读信</span></a></h2><p>这一节一句话：四层设备只看信封，七层设备才拆开读信纸。</p><p>把一个请求想象成一封信：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 信封：                                    │</span></span>
<span class="line"><span>│   收件地址 192.168.1.40（IP）             │</span></span>
<span class="line"><span>│   收件窗口 9080 端口                      │  ← 四层设备只读到这里</span></span>
<span class="line"><span>│ ───────────────────────────────────────  │</span></span>
<span class="line"><span>│ 信纸（HTTP 内容）：                        │</span></span>
<span class="line"><span>│   &quot;GET /usercenter/api/list HTTP/1.1&quot;    │  ← 七层设备才会拆开读</span></span>
<span class="line"><span>│   Header: Authorization: xxx             │</span></span>
<span class="line"><span>│   Body: {&quot;page&quot;: 2}                      │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>四层 = 传输层：看信封（IP + 端口），不拆信</li><li>七层 = 应用层：拆信读内容，知道你要干嘛（查哪个路径、带什么登录态）</li></ul><p>（&quot;层&quot;指 OSI 网络模型——一封信从寄出到送达要过七道工序，第四道管&quot;送到哪个端口&quot;，第七道管&quot;信里到底写了什么&quot;。模型记不住没关系，记住&quot;看信封的便宜、拆信的贵&quot;就够了。）</p><p>两种设备的分工与身价：</p><table><thead><tr><th></th><th>四层设备（LVS）</th><th>七层设备（APISIX/nginx）</th></tr></thead><tbody><tr><td>能做的事</td><td>只能按 IP:端口 分</td><td>按路径/Header/Cookie/Body 做任何事</td></tr><tr><td>抗量</td><td>百万级连接</td><td>数万~数十万 QPS</td></tr><tr><td>代价</td><td>极便宜：不拆包，只记一张转发表</td><td>贵：每个请求完整解析一遍 HTTP</td></tr></tbody></table><p>四层为什么扛得住百万连接？它对每封信只做&quot;扫条码 → 换单转发&quot;，开销几乎恒定；七层每封都要&quot;拆封、通读、决策、重封&quot;，天然贵一个量级。所以大厂的经典分工是：便宜的四层扛量，昂贵的七层干精活。</p><p>顺带把身边的设备归个类：keepalived 的 VIP 连四层都不算（只管 IP，端口都不看）；Windows portproxy、云 SLB 的&quot;四层监听&quot;是四层；nginx 的 <code>location</code> + <code>proxy_pass</code>、APISIX 的 <code>uris: /usercenter/*</code>、云 SLB 的&quot;七层监听&quot;是七层。</p><hr><h2 id="六、lvs-传达室里的自动分拣机" tabindex="-1"><a class="header-anchor" href="#六、lvs-传达室里的自动分拣机"><span>六、LVS：传达室里的自动分拣机</span></a></h2><h3 id="_6-1-它是什么" tabindex="-1"><a class="header-anchor" href="#_6-1-它是什么"><span>6.1 它是什么</span></a></h3><p>LVS（Linux Virtual Server）不是一个装出来的软件，是 Linux 内核自带的转发引擎，内核里那个模块叫 IPVS。<code>modprobe ip_vs</code> 给它插上电；<code>ipvsadm</code> 只是一支笔，往它肚子里那张表格填数据。它快的唯一原因：转发在内核里完成。（内核：操作系统最里层、直接管硬件的那一层；普通程序跑在&quot;用户态&quot;，数据包要递到程序手里得绕一大圈——LVS 省掉了这一圈。）</p><p>用传达室的比方：所有包裹进大楼必经传达室（内核），LVS 就是传达室里装的自动分拣机——包裹到传达室就被机器改写收件人直接转走，根本不用递给任何程序处理。</p><h3 id="_6-2-配置-在纸条上写三行字" tabindex="-1"><a class="header-anchor" href="#_6-2-配置-在纸条上写三行字"><span>6.2 配置 = 在纸条上写三行字</span></a></h3><p>实测（WSL 内核加载 ip_vs 后）：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">modprobe</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> ip_vs</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">                                # 插电源</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ipvsadm</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -A</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -t</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> 172.66.0.200:9081</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> rr</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">        # 纸条第一行: 到这个VIP:端口的包,按&quot;轮流&quot;分</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ipvsadm</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -a</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -t</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> 172.66.0.200:9081</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -r</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> 172.66.0.11:9080</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -m</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # 名单①: 网关1</span></span>
<span class="line"><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">ipvsadm</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -a</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -t</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> 172.66.0.200:9081</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -r</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> 172.66.0.12:9080</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -m</span><span style="--shiki-light:#A0A1A7;--shiki-light-font-style:italic;--shiki-dark:#7F848E;--shiki-dark-font-style:italic;">   # 名单②: 网关2</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>（<code>-m</code> 是 NAT 模式：分拣时顺手改写信封上的收件人，并做端口翻译 9081→9080。）</p><p>看这张内核里的纸条：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ipvsadm -Ln</span></span>
<span class="line"><span>Prot LocalAddress:Port Scheduler</span></span>
<span class="line"><span>  -&gt; RemoteAddress:Port           Forward Weight ActiveConn InActConn</span></span>
<span class="line"><span>TCP  172.66.0.200:9081 rr</span></span>
<span class="line"><span>  -&gt; 172.66.0.11:9080             Masq    1      0          3</span></span>
<span class="line"><span>  -&gt; 172.66.0.12:9080             Masq    1      0          3</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>算法（怎么分）除了 <code>rr</code>（轮询：一人一发），还有 <code>wrr</code>（加权轮询：好机器多分）、<code>lc</code>（最少连接：谁手头闲给谁）、<code>sh</code>（源 IP 哈希：同一个客人永远去同一个窗口，即会话保持）。记住 rr 和 wrr 够应付九成场景。</p><h3 id="_6-3-实测一-轮询分流" tabindex="-1"><a class="header-anchor" href="#_6-3-实测一-轮询分流"><span>6.3 实测一：轮询分流</span></a></h3><p>打 6 发的命令就是一条循环——<code>-o /dev/null</code> 丢掉页面内容，<code>-w &quot;%{http_code} &quot;</code> 只打状态码，6 发一行看完（6.4 节的 <code>000</code> 也是它打出来的）；<code>--noproxy &#39;*&#39;</code> 让 curl 直连、别被环境里的 HTTP 代理劫走：</p><div class="language-bash line-numbers-mode" data-highlighter="shiki" data-ext="bash" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-bash"><span class="line"><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">for</span><span style="--shiki-light:#E45649;--shiki-dark:#E06C75;"> i</span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;"> in</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> $(</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;">seq</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> 6</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">); </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">do</span><span style="--shiki-light:#4078F2;--shiki-dark:#61AFEF;"> curl</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -s</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --noproxy</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &#39;*&#39;</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -o</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> /dev/null</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> -w</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> &quot;%{http_code} &quot;</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> http://172.66.0.200:9081/hello</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">; </span><span style="--shiki-light:#A626A4;--shiki-dark:#C678DD;">done</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;">; </span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;">echo</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>连打 6 发请求，看内核自己的账本：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ipvsadm -Ln --stats</span></span>
<span class="line"><span>  -&gt; 172.66.0.11:9080        3 conns    1218 bytes</span></span>
<span class="line"><span>  -&gt; 172.66.0.12:9080        3 conns    1218 bytes</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>6 发一边 3 发，分毫不差。这就是&quot;四层分流&quot;的全部真相——只改信封上的收件人，不拆信不看内容。</p><h3 id="_6-4-实测二-裸-lvs-的翻车现场" tabindex="-1"><a class="header-anchor" href="#_6-4-实测二-裸-lvs-的翻车现场"><span>6.4 实测二：裸 LVS 的翻车现场</span></a></h3><p>停掉名单上的一台后端（模拟网关宕机），再打 3 发：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>再打3发: 000 200 000      ← 000 = 超时，一半请求寄给了死人</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>裸 LVS 不做健康检查——名单上还写着死人的名字，它照样轮流寄。所以生产上 LVS 从不裸奔，由 keepalived 全权打理（见 6.6）。</p><p>这一幕是理解整个架构的钥匙：分拣机聪明在快，蠢在不管死活；管死活的活儿，交给别人。</p><h3 id="_6-5-实测三-扩容-名单加一行字" tabindex="-1"><a class="header-anchor" href="#_6-5-实测三-扩容-名单加一行字"><span>6.5 实测三：扩容 = 名单加一行字</span></a></h3><p>名单里加入第三台网关，再打 6 发：</p><div class="language-text line-numbers-mode" data-highlighter="shiki" data-ext="text" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-text"><span class="line"><span>$ ipvsadm -a -t 172.66.0.200:9081 -r 172.66.0.34:9080 -m</span></span>
<span class="line"><span>（打 6 发后）</span></span>
<span class="line"><span>  -&gt; 172.66.0.11:9080    累计连接 +2</span></span>
<span class="line"><span>  -&gt; 172.66.0.12:9080    累计连接 +2</span></span>
<span class="line"><span>  -&gt; 172.66.0.34:9080    累计连接 +2     ← 新机器立刻开始接活</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>再玩个花的：把算法换成 wrr、给第三台权重 4（好机器多干活），连打 10 发，增量正好 2 : 2 : 6——权重一行字，比例立刻变。</p><p>LVS 里的全部配置就五样：VIP:端口（收件地址）、算法（怎么分）、模式（怎么改包）、后端名单（分给谁，必须认识每一台网关）、每台权重。它不知道路径、域名、路由规则、健康状态——故意这么蠢，蠢 = 快。聪明事全在别人那儿：路径归网关，健康归 keepalived。</p><h3 id="_6-6-keepalived-lvs-本来就是一套" tabindex="-1"><a class="header-anchor" href="#_6-6-keepalived-lvs-本来就是一套"><span>6.6 keepalived + LVS：本来就是一套</span></a></h3><p>keepalived 的另一半工作，就是替 LVS 管这张纸条（这也解释了为什么架构图里它俩总画在同一个框里）：</p><div class="language-conf line-numbers-mode" data-highlighter="shiki" data-ext="conf" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-conf"><span class="line"><span>vrrp_instance VI_1 {</span></span>
<span class="line"><span>    state MASTER                   # 前半身: 心跳 + VIP 漂移（另一台: BACKUP / 90）</span></span>
<span class="line"><span>    interface ens192</span></span>
<span class="line"><span>    virtual_router_id 51</span></span>
<span class="line"><span>    priority 100</span></span>
<span class="line"><span>    advert_int 1</span></span>
<span class="line"><span>    virtual_ipaddress {</span></span>
<span class="line"><span>        192.168.1.40/24            # 与下方 virtual_server 用同一个 VIP</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>virtual_server 192.168.1.40 9080 { # 后半身: 替 LVS 管转发表</span></span>
<span class="line"><span>    delay_loop 3                   #   每3秒给名单全员做一次体检</span></span>
<span class="line"><span>    lb_algo wrr                    #   加权轮询</span></span>
<span class="line"><span>    lb_kind NAT</span></span>
<span class="line"><span>    protocol TCP                   #   不写这行, keepalived 默认按 UDP 处理, TCP 服务直接配错</span></span>
<span class="line"><span>    real_server 192.168.1.31 9080 {  #   名单第1行</span></span>
<span class="line"><span>        weight 1</span></span>
<span class="line"><span>        TCP_CHECK {                #   体检: 尝试TCP连接</span></span>
<span class="line"><span>            connect_port 9080</span></span>
<span class="line"><span>            connect_timeout 2</span></span>
<span class="line"><span>            retry 2</span></span>
<span class="line"><span>            delay_before_retry 1</span></span>
<span class="line"><span>        }                          #   不通→自动摘除; 复活→自动写回</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    real_server 192.168.1.32 9080 {  #   名单第2行, 结构同上</span></span>
<span class="line"><span>        weight 1</span></span>
<span class="line"><span>        TCP_CHECK {</span></span>
<span class="line"><span>            connect_port 9080</span></span>
<span class="line"><span>            connect_timeout 2</span></span>
<span class="line"><span>            retry 2</span></span>
<span class="line"><span>            delay_before_retry 1</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>keepalived 一肩挑三件事：VIP 漂移（机器级故障）、LVS 转发表（怎么分流）、后端健康检查（进程级故障自动摘除）。扩容 = 照抄一段 <code>real_server</code> 改 IP，两台 keepalived.conf 同步改，reload 生效，30 秒的活。</p><hr><h2 id="七、完整-keepalived-conf-四大块与三处差异" tabindex="-1"><a class="header-anchor" href="#七、完整-keepalived-conf-四大块与三处差异"><span>七、完整 keepalived.conf：四大块与三处差异</span></a></h2><p>一份完整模板（已通过 <code>keepalived -t</code> 语法校验，退出码 0）。先记住四大块各自的一句话职责，再看就不晕：</p><ul><li><code>global_defs</code>：署名与安全底线</li><li><code>vrrp_script</code>：体检项目</li><li><code>vrrp_instance</code>：门牌小队（keepalived 的前半身）</li><li><code>virtual_server</code>：LVS 名单（后半身，不用 LVS 就整段删）</li></ul><div class="language-conf line-numbers-mode" data-highlighter="shiki" data-ext="conf" style="--shiki-light:#383A42;--shiki-dark:#abb2bf;--shiki-light-bg:#FAFAFA;--shiki-dark-bg:#282c34;"><pre class="shiki shiki-themes one-light one-dark-pro vp-code"><code class="language-conf"><span class="line"><span># ---------- 全局定义 ----------</span></span>
<span class="line"><span>global_defs {</span></span>
<span class="line"><span>    router_id GW_M1                # 本机署名(日志用), 另一台写 GW_M2</span></span>
<span class="line"><span>    enable_script_security         # 体检脚本只许root执行(防篡改后自动提权)</span></span>
<span class="line"><span>    script_user root</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- 体检项目 ----------</span></span>
<span class="line"><span>vrrp_script chk_apisix {</span></span>
<span class="line"><span>    script &quot;/usr/bin/curl -s -o /dev/null http://127.0.0.1:9080/&quot;</span></span>
<span class="line"><span>    interval 3</span></span>
<span class="line"><span>    timeout 2</span></span>
<span class="line"><span>    weight -30</span></span>
<span class="line"><span>    fall 2</span></span>
<span class="line"><span>    rise 2</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- VIP 小队 ----------</span></span>
<span class="line"><span>vrrp_instance VI_APISIX {</span></span>
<span class="line"><span>    state MASTER                   # ★M2改: BACKUP</span></span>
<span class="line"><span>    interface ens192               # ip route 查真实网卡名</span></span>
<span class="line"><span>    virtual_router_id 51           # 两台一致, 同网段全网唯一</span></span>
<span class="line"><span>    priority 100                   # ★M2改: 90</span></span>
<span class="line"><span>    advert_int 1</span></span>
<span class="line"><span>    # nopreempt                    # 可选: 大哥修好不抢回, 防二次抖动(只能用在BACKUP侧)</span></span>
<span class="line"><span>    # unicast_src_ip 192.168.1.31  # 可选: 交换机禁组播时改单播, 两台互换</span></span>
<span class="line"><span>    # unicast_peer { 192.168.1.32 }</span></span>
<span class="line"><span>    authentication {</span></span>
<span class="line"><span>        auth_type PASS</span></span>
<span class="line"><span>        auth_pass Ap1six           # 前8位有效, 两台一致</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    virtual_ipaddress {</span></span>
<span class="line"><span>        192.168.1.40/24            # 争夺的VIP, 前端/DNS只填这个</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    track_script { chk_apisix }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span># ---------- LVS 名单(选配, 不玩LVS整段删) ----------</span></span>
<span class="line"><span>virtual_server 192.168.1.40 9080 {</span></span>
<span class="line"><span>    delay_loop 3</span></span>
<span class="line"><span>    lb_algo wrr</span></span>
<span class="line"><span>    lb_kind NAT</span></span>
<span class="line"><span>    protocol TCP</span></span>
<span class="line"><span>    real_server 192.168.1.31 9080 {</span></span>
<span class="line"><span>        weight 1</span></span>
<span class="line"><span>        TCP_CHECK { connect_port 9080  connect_timeout 2  retry 2  delay_before_retry 1 }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    real_server 192.168.1.32 9080 {</span></span>
<span class="line"><span>        weight 1</span></span>
<span class="line"><span>        TCP_CHECK { connect_port 9080  connect_timeout 2  retry 2  delay_before_retry 1 }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>模板里注释掉的 <code>nopreempt</code> 单独说透。keepalived 默认是&quot;抢位模式&quot;（preempt）：priority 100 的大哥修好重启那一刻，立刻把 VIP 抢回来——3.6 节第三幕演的就是这个。抢位有代价：门牌搬家 = VIP 漂移 + 免费 ARP 全网刷新，全网有几秒抖动窗口；而刚修好的机器往往还没热身（缓存是冷的、连接池是空的），立刻接全量流量，可能引发第二次故障。</p><p><code>nopreempt</code> 把&quot;抢位&quot;改成&quot;让位到底&quot;：大哥修好后不抢，继续让现在的持牌者干活，自己安静当备胎，直到对方也倒下才接管。两条配套铁律：</p><ol><li><code>nopreempt</code> 只能写在 <code>state BACKUP</code> 的机器上——<code>state MASTER</code> 的实例配它，keepalived 直接拒绝启动。理由也直白：MASTER 的定义就是&quot;开机必抢&quot;，再配&quot;不抢&quot;自相矛盾。</li><li>所以想全局不抢，两台都得写 <code>state BACKUP</code>：开机第一轮没人持牌，仍按 priority 定初始归属（100 那台先拿到），之后谁修好都不抢。</li></ol><p>代价也想清楚：修好的大哥长期闲着，流量一直压在备胎上，&quot;哪台在干活&quot;和&quot;哪台是大哥&quot;不再对齐——认门牌只能靠 <code>ip addr</code>，不能靠记忆。两台内网网关的常规场景，默认抢位就够；只有&quot;大哥修好立刻抢回&quot;确实引发过二次故障的机器，才值得换 <code>nopreempt</code>。</p><p>两台机器的差异背下来就三处：<code>router_id</code>、<code>state</code>、<code>priority</code>（若启用单播再加 src/peer 互换）。其余逐字节相同。</p><p>改完自查一条：<code>keepalived -t -f /etc/keepalived/keepalived.conf</code>——只测语法不运行，生产改配置的保命习惯。</p><hr><h2 id="八、公司两台-vs-大厂分层-该用哪种形态" tabindex="-1"><a class="header-anchor" href="#八、公司两台-vs-大厂分层-该用哪种形态"><span>八、公司两台 vs 大厂分层：该用哪种形态</span></a></h2><p>先说人话：机器少就挤在一起，机器多、流量大才分层。两种形态用的都是这篇文章讲过的同一套零件。</p><p><img src="/assets/img-002-C0AXvMua.png" alt="大厂分层接入架构" loading="lazy"></p><table><thead><tr><th></th><th>同机形态（两台）</th><th>分层形态（大厂）</th></tr></thead><tbody><tr><td>机器数</td><td>2 台</td><td>2 台专机 LVS + 4~N 台网关</td></tr><tr><td>每台机器上跑什么</td><td>keepalived + APISIX</td><td>LVS 机：keepalived + LVS；网关机：纯 APISIX</td></tr><tr><td>分流在哪层做</td><td>APISIX 的 upstream 自带轮询</td><td>LVS 四层分流（百万级连接）</td></tr><tr><td>适合谁</td><td>绝大多数中小公司、内网网关</td><td>公网大流量、网关超过 3 台</td></tr><tr><td>拆层的信号</td><td>——</td><td>网关要独立扩缩容；四层扛量七层干精活要分开算钱</td></tr></tbody></table><p>分层形态的精髓是两层各干各的粗细活：LVS 只看 IP:端口（四层，便宜，扛量），网关集群拆信干细活（七层，贵，精活）；网关无状态（配置全在 etcd，watch 实时同步到每一台），加机器即扩容，LVS 名单添一行完事。</p><p>而两层防挂的手法你已经全会了：接入层自身就是一对 keepalived 主备 + VIP 漂移，和两台网关之间玩的是同一个把戏。如果主备两台同时挂呢？——双机房各一套接入层，DNS 把域名切到另一机房兜底（分钟级）；再往上才是异地多活。工程上不存在&quot;永不挂的东西&quot;，追求的是&quot;挂了用户感觉不到&quot;：消灭单点 + 恢复自动化，两条而已。</p><p>公司两台网关的裁剪建议：删掉 virtual_server 整段（APISIX 的 upstream 自带轮询，不需要 LVS），剩下的就是&quot;keepalived 只管门牌 + 网关死也让位&quot;的最小可靠形态——本文第四节那张图。</p><hr><h2 id="九、生产部署检查表" tabindex="-1"><a class="header-anchor" href="#九、生产部署检查表"><span>九、生产部署检查表</span></a></h2><p>容器里遇不到、真机上必查的几件事，逐条打勾再上岗：</p><ul class="task-list-container"><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-0" disabled="disabled"><label class="task-list-item-label" for="task-item-0"> 网卡名：<code>ip route | awk &#39;/default/ {print $5}&#39;</code> 查真实名字，替换配置里的 <code>interface</code></label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-1" disabled="disabled"><label class="task-list-item-label" for="task-item-1"> 防火墙放行心跳：VRRP 是 IP 协议号 112，不是端口！<code>ufw allow proto 112 from &lt;对端IP&gt;</code>（firewalld 用 rich rule）；排障期可临时 <code>ufw disable</code> 对照</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-2" disabled="disabled"><label class="task-list-item-label" for="task-item-2"> 组播是否被禁：部分交换机吞掉 224.0.0.18。症状 = 两台都说自己 MASTER（双双抢 VIP）。解法 = 配置改单播（<code>unicast_src_ip</code> / <code>unicast_peer</code>）</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-3" disabled="disabled"><label class="task-list-item-label" for="task-item-3"> 演练制度：上岗前至少完整演练一次&quot;拔电→接管→复活→抢回&quot;；以后每次变更（换网关、升级配置）后重演一遍。没演练过的高可用 = 没有高可用</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-4" disabled="disabled"><label class="task-list-item-label" for="task-item-4"> 网关监听地址：确认网关配置监听 <code>0.0.0.0:9080</code>（APISIX 的 <code>node_listen</code> 默认就是），写死单机 IP 是漂移后没人接电话的经典翻车点</label></li><li class="task-list-item"><input type="checkbox" class="task-list-item-checkbox" id="task-item-5" disabled="disabled"><label class="task-list-item-label" for="task-item-5"> 别忘了：<code>keepalived -t</code> 语法自查 → <code>systemctl enable --now keepalived</code> → <code>ip addr</code> 确认 VIP 归属 → <code>journalctl -u keepalived -f</code> 看心跳对白</label></li></ul><hr><h2 id="十、faq-与踩坑实录" tabindex="-1"><a class="header-anchor" href="#十、faq-与踩坑实录"><span>十、FAQ 与踩坑实录</span></a></h2><p><strong>Q1：两台都显示 MASTER、IP 时通时断？</strong><br> 脑裂（split-brain）典型症状：心跳不通但两台都活着，各抢各的 VIP。先查防火墙 112 和交换机组播，再考虑配双心跳路径。内网双机场景概率极低，但症状要认得。</p><p><strong>Q2：curl VIP 返回 000 是什么意思？</strong><br> 超时无应答。本文 6.4 节的实测：后端死了但 LVS 名单没摘除，一半请求寄给死人。带上 keepalived 的健康检查（或任何带探活的负载均衡）就不会发生。</p><p><strong>Q3：为什么是 3~4 秒接管，不是 0 秒？</strong></p><p>接管时间 = 判死时间 + 搬门牌时间，两段都能算出来。</p><p>判死时间有精确公式（VRRP 协议规定）：<strong>判死时间 = 3 × advert_int + (256 − priority) / 256</strong>。代入 KA2（priority 90）：3 × 1 + 166/256 ≈ 3.65 秒。公式的两半各有用意：</p><ul><li><strong>3 × advert_int</strong>：BACKUP 要连丢 3 拍心跳才判 MASTER 死，不是丢 1 拍就判。网络偶发丢包太常见（网卡忙、交换机抖一下），一丢就切等于天天误切；连丢 3 拍，基本只有真死机做得到。</li><li><strong>(256 − priority) / 256</strong>：权位越低，额外多等一小会（KA2 约 0.65 秒）。如果还有第三台 priority 95 的备胎，它 0.24 秒后就到点、先到先接管；KA2 晚 0.65 秒才到点，到点前收到别人的心跳就继续待命——多台备胎不会同时发难、来回抢门牌。</li></ul><p>搬门牌时间（零点几到几秒）：netlink 把 VIP 挂上网卡是毫秒级，大头是免费 ARP 刷新——交换机的 MAC 表、邻居主机的 ARP 缓存要各自认下&quot;VIP 换 MAC 了&quot;，不同设备节奏不同，典型零点几秒、慢的几秒。3.6 节&quot;拔网线实测约 6 秒&quot;里超出 3.65 秒的部分，就是这一段。</p><p>想更快？把 advert_int 从 1 调到 0.5，判死变 1.5 + 0.65 ≈ 2.15 秒。但代价翻倍地来：心跳包数量 ×2；判死窗口变窄，网络一抖就容易凑满 3 丢 → 误切换变多；而每次切换本身就带一次 GARP 全网抖动。省 1.5 秒、换来更多次抖，通常不划算——所以 1 秒是甜点位：几秒内接管，用户的浏览器自动重试基本把缝隙盖住。</p><p><strong>Q4：VIP 漂回 MASTER 后，前几秒请求还是旧机器应答？</strong><br> 正常现象：交换机 ARP 缓存还没刷新。用户侧浏览器自动重试可吸收；介意的话用 <code>nopreempt</code> 让大哥修好后安静当备胎，不抢回（&quot;不抢回&quot;到底什么意思、为什么只能配在 BACKUP 侧，展开在第七节模板后面那段）。</p><p><strong>Q5：keepalived 到底占不占端口？</strong><br> 不占任何 TCP/UDP 端口。心跳走 IP 协议号 112。<code>ss -tlnp</code> 里永远找不到它——找不到才说明它健康。</p><p><strong>Q6：为什么我的 LVS 实验不生效，流量全去了同一台？</strong><br> 检查宿主机有没有别的 DNAT 抢先。笔者的实测翻车：网关容器发布过 <code>-p 9080:9080</code>，docker 的 DNAT 规则把宿主机上所有目的端口 9080 的包直接劫走，LVS 根本没轮到出手。换个没被占用的端口（如 9081，LVS 顺手做端口翻译）立刻正常。</p><hr><h2 id="十一、费曼自检-合上文章-你能答出几条" tabindex="-1"><a class="header-anchor" href="#十一、费曼自检-合上文章-你能答出几条"><span>十一、费曼自检：合上文章，你能答出几条</span></a></h2><p>学没学会的唯一检验标准：讲给别人听。不看文章回答下面七条，卡壳的那条，就是回去重读的那节：</p><ol><li>为什么不能让前端&quot;记住两个 IP 自己切换&quot;？（第一节）</li><li>VIP 和普通 IP 差在哪？keepalived 转不转发业务流量？（第二、四节）</li><li>两台机器的 keepalived.conf 一共差几处？各是什么？（第三、七节）</li><li>机器没死、网关进程死了，流量为什么会黑洞？怎么治？（3.7 节）</li><li>四层和七层设备各自&quot;看信的哪一部分&quot;？为什么四层便宜扛量？（第五节）</li><li>裸 LVS 为什么会把请求寄给死人？keepalived 怎么补上这个洞？（第六节）</li><li>公司两台网关的形态里，哪一段配置可以直接删掉？为什么？（第八节）</li></ol><p>七条全能脱口而出，这篇就可以翻篇了。</p><hr><h2 id="参考资料" tabindex="-1"><a class="header-anchor" href="#参考资料"><span>参考资料</span></a></h2><ul><li>keepalived 官方文档与 man page：<code>man keepalived.conf</code>（配置项最全的一手来源）</li><li>Linux Virtual Server 项目：<a href="https://www.linuxvirtualserver.org" target="_blank" rel="noopener noreferrer">https://www.linuxvirtualserver.org</a></li><li>IPVS 内核文档：内核源码 <code>Documentation/networking/ipvs.rst</code></li><li>Julia Evans 的技术写作方式（比喻 + 小实验）：<a href="https://jvns.ca" target="_blank" rel="noopener noreferrer">https://jvns.ca</a></li><li>Brendan Gregg 的证据纪律（结论必须配真实输出）：<a href="https://www.brendangregg.com" target="_blank" rel="noopener noreferrer">https://www.brendangregg.com</a></li><li>Google SRE Book（演练与故障排查方法论）：<a href="https://sre.google/books/" target="_blank" rel="noopener noreferrer">https://sre.google/books/</a></li></ul><hr><p>➡️ 下一篇：系列完结（规划中：《keepalived 脑裂与仲裁》《LVS DR 模式与公网接入》）</p>`,190)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};